fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut low: usize = 0;
    let mut high: usize = v.len() - 1;
    
    while low < high {
        let mid = low + (high - low) / 2;
        
        if v[mid] < k {
            // Target must be in the right half (including mid+1)
            low = mid + 1;
        } else {
            // Target is at mid or in the left half
            high = mid;
        }
    }
    
    // At this point, low == high, and v[low] == k (guaranteed by problem)
    low
}